create or replace function public.get_order_tracking(p_order_id uuid,p_tracking_token uuid) returns jsonb language sql stable security definer set search_path=public as $$
select jsonb_build_object('id',o.id,'number',o.number,'customer_name',o.customer_name,'primary_phone',o.primary_phone,'secondary_phone',o.secondary_phone,'order_type',o.order_type,'payment_method',o.payment_method,'payment_status',o.payment_status,'special_instructions',o.special_instructions,'status',o.status,'subtotal',o.subtotal,'delivery_fee',o.delivery_fee,'total',o.total,'estimated_minutes',o.estimated_minutes,'assigned_driver_id',o.assigned_driver_id,'assignment_accepted_at',o.assignment_accepted_at,'created_at',o.created_at,'customer_addresses',(select coalesce(jsonb_agg(a),'[]') from customer_addresses a where a.order_id=o.id),'order_items',(select coalesce(jsonb_agg(i),'[]') from order_items i where i.order_id=o.id),'order_events',(select coalesce(jsonb_agg(e order by e.occurred_at),'[]') from order_events e where e.order_id=o.id),'delivery_issues','[]'::jsonb) from orders o where o.id=p_order_id and o.tracking_token=p_tracking_token
$$;
revoke all on function public.get_order_tracking(uuid,uuid) from public;
grant execute on function public.get_order_tracking(uuid,uuid) to anon,authenticated;
